messages.content:
Tool response:
Tool: reschedule_appointment
Description: Reschedule Appointment
Parameters:
    {
      "type": "object",
      "properties": {
        "appointment_id": {
          "type": "integer",
          "description": "Internal ID of the appointment to reschedule",
          "title": "Appointment Id"
        },
        "new_datetime": {
          "type": "string",
          "title": "New Datetime",
          "description": "New appointment datetime in ISO format (e.g., 2025-01-22T15:30:00)"
        },
        "room_id": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "title": "Room Id",
          "description": "Optional room ID to assign to the appointment. If not provided, no room change occurs."
        }
      },
      "required": [
        "appointment_id",
        "new_datetime"
      ]
    }
